private inline fun icon(name: String, autoMirror: Boolean = false, block: ImageVector.Builder.() -> ImageVector.Builder): ImageVector =
    ImageVector.Builder(
        name = name,
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 24f,
        viewportHeight = 24f,
        autoMirror = autoMirror,
    ).block().build()

/** Same defaults as material-icons' `materialPath`: solid black fill, no stroke. */
private inline fun ImageVector.Builder.materialPath(pathBuilder: PathBuilder.() -> Unit): ImageVector.Builder =
    path(
        fill = SolidColor(Color.Black),
        fillAlpha = 1f,
        stroke = null,
        strokeAlpha = 1f,
        strokeLineWidth = 1f,
        strokeLineCap = StrokeCap.Butt,
        strokeLineJoin = StrokeJoin.Bevel,
        strokeLineMiter = 1f,
        pathFillType = PathFillType.NonZero,
        pathBuilder = pathBuilder,
    )
